insert into public.cnae_checklist_profiles (cnae_prefix,title,description,technical_notice,revision,source_reference)
values
 ('','Base obrigatória da visita SST','Roteiro base aplicado a qualquer atividade econômica antes dos complementos específicos do CNAE.','Use este roteiro para evitar omissões. A aplicabilidade final deve ser validada pelo profissional responsável conforme PGR, atividades efetivas, instalações e legislação vigente.',1,'Normas Regulamentadoras vigentes — Ministério do Trabalho e Emprego'),
 ('561','Restaurantes, lanchonetes e serviços de alimentação','Complemento técnico para CNAEs do grupo 561: restaurantes, lanchonetes e atividades de alimentação e bebidas.','O CNAE direciona a inspeção, mas não substitui a análise de riscos do estabelecimento. Marque N/A somente depois de verificar que a condição realmente não existe.',1,'NR-01, NR-05, NR-06, NR-07, NR-10, NR-11, NR-12, NR-17, NR-20, NR-23, NR-24 e NR-26')
on conflict (cnae_prefix,title,revision) do update set description=excluded.description, technical_notice=excluded.technical_notice, source_reference=excluded.source_reference, active=true, updated_at=now();

with p as (select id from public.cnae_checklist_profiles where cnae_prefix='' and title='Base obrigatória da visita SST' and revision=1)
insert into public.cnae_checklist_profile_items (profile_id,regulatory_standard_code,section_title,prompt,guidance,required,sort_order)
select p.id,v.nr,v.section,v.prompt,v.guidance,true,v.ord from p cross join (values
 (10,'NR-01','Gestão de riscos','PGR/GRO está disponível, atualizado e compatível com as atividades observadas?','Conferir inventário de riscos, plano de ação, responsáveis e evidências de acompanhamento.'),
 (20,'NR-01','Gestão de riscos','Os riscos físicos, químicos, biológicos, ergonômicos e de acidentes foram reavaliados para mudanças recentes?','Registrar alterações de processo, layout, equipamentos, produtos, jornada ou efetivo.'),
 (30,'NR-05','Organização e prevenção','A organização de prevenção (CIPA/designado) está definida e possui registros de capacitação e reuniões?','Verificar dimensionamento, designação e ações preventivas/assédio.'),
 (40,'NR-06','EPI','Os EPIs necessários estão definidos, com CA válido, entrega registrada, treinamento e reposição?','Conferir adequação ao risco e uso real observado, não apenas o estoque.'),
 (50,'NR-07','Saúde ocupacional','PCMSO e ASOs estão válidos para os riscos e funções atuais?','Conferir admissional, periódico, retorno, mudança de risco/função e demissional quando aplicável.'),
 (60,'NR-10','Instalações elétricas','Quadros, circuitos, tomadas, extensões e intervenções elétricas estão identificados, íntegros e protegidos?','Registrar improvisos, condutores expostos, sobrecarga, acesso indevido e necessidade de bloqueio.'),
 (70,'NR-17','Ergonomia','Postos, ritmo, mobiliário, levantamento de cargas e pausas foram avaliados?','Observar postura, repetitividade, alcances, alternância de tarefas e queixas dos trabalhadores.'),
 (80,'NR-23','Emergência e incêndio','Rotas de fuga, saídas, extintores, sinalização e acesso aos equipamentos estão desobstruídos?','Verificar validade/manutenção e se as pessoas sabem como agir em emergência.'),
 (90,'NR-24','Condições sanitárias','Sanitários, vestiários, água potável, áreas de refeição e limpeza oferecem condições adequadas?','Verificar conservação, higiene, separação de áreas e disponibilidade conforme efetivo.'),
 (100,'NR-26','Sinalização e produtos','Riscos, áreas, equipamentos de emergência e produtos químicos estão identificados e sinalizados?','Conferir rótulos, FISPQ, pictogramas e sinalização visível/legível.'),
 (110,'NR-12','Máquinas e equipamentos','Máquinas e equipamentos existentes possuem proteção, partida/parada segura e manutenção controlada?','Se não houver máquina ou equipamento abrangido, marcar N/A com justificativa.')
) v(ord,nr,section,prompt,guidance)
on conflict (profile_id,sort_order) do update set regulatory_standard_code=excluded.regulatory_standard_code,section_title=excluded.section_title,prompt=excluded.prompt,guidance=excluded.guidance,required=excluded.required;

with p as (select id from public.cnae_checklist_profiles where cnae_prefix='561' and title='Restaurantes, lanchonetes e serviços de alimentação' and revision=1)
insert into public.cnae_checklist_profile_items (profile_id,regulatory_standard_code,section_title,prompt,guidance,required,sort_order)
select p.id,v.nr,v.section,v.prompt,v.guidance,true,v.ord from p cross join (values
 (10,'NR-01','Cozinha e produção','O inventário do PGR contempla cortes, queimaduras, escorregões, calor, vapor, ruído, produtos químicos e movimentação de cargas?','Conferir cozinha, estoque, salão e entrega no inventário e plano de ação.'),
 (20,'NR-06','Cozinha e produção','A equipe usa EPI adequado para calor, corte, limpeza e piso molhado?','Verificar luvas adequadas à atividade, avental, calçado antiderrapante e orientação de uso.'),
 (30,'NR-12','Máquinas e equipamentos','Fatiadores, liquidificadores industriais, batedeiras, moedores e demais máquinas possuem proteção e comando seguro?','Verificar guardas, integridade, parada, limpeza com equipamento desligado e proibição de anular proteções.'),
 (40,'NR-12','Máquinas e equipamentos','Facas, lâminas e utensílios cortantes têm armazenamento, transporte e descarte seguro?','Conferir suportes, bainhas, local de lavagem e risco de contato na pia.'),
 (50,'NR-17','Ergonomia e organização','Bancadas, pias, fogões, câmaras e áreas de preparo permitem postura e alcance adequados?','Observar altura, torção, trabalho estático, repetitividade e organização dos materiais mais usados.'),
 (60,'NR-17','Ergonomia e organização','Há meios seguros para transporte e armazenamento de caixas, botijões e insumos?','Registrar peso, frequência, altura de empilhamento, carrinhos, corredores e treinamento de movimentação.'),
 (70,'NR-10','Instalações elétricas','Equipamentos de cozinha, tomadas, extensões e quadros elétricos estão protegidos contra umidade, calor e sobrecarga?','Verificar cabos danificados, benjamins, tomadas próximas a água, aterramento e acesso ao quadro.'),
 (80,'NR-20','GLP, calor e vapor','Botijões, central de GLP, registros, mangueiras e ventilação estão em condição segura?','Inspecionar vazamentos, proteção contra impacto, afastamentos, identificação e acesso aos registros. N/A somente se não houver GLP.'),
 (90,'NR-23','GLP, calor e vapor','Extintores adequados à cozinha e à área de GLP estão acessíveis, sinalizados e dentro da validade?','Verificar desobstrução, tipo adequado e conhecimento da equipe sobre acionamento e abandono.'),
 (100,'NR-23','Rotas e pisos','Pisos, passagens, portas e rotas de fuga estão livres, secos e com controle de escorregamento?','Registrar gordura/água no piso, tapetes soltos, degraus, iluminação e sinalização de piso molhado.'),
 (110,'NR-24','Higiene e conforto','Áreas de lavagem, sanitários, vestiários, água potável e local de refeição estão limpos e organizados?','Observar separação entre higienização, alimentos, resíduos e pertences pessoais.'),
 (120,'NR-26','Produtos químicos','Produtos de limpeza estão identificados, armazenados separadamente e com informação de segurança disponível?','Conferir rotulagem, diluição, incompatibilidades, FISPQ e EPI de limpeza.'),
 (130,'NR-01','Calor e ventilação','Exposição a calor, vapor, ventilação deficiente e pausas da equipe foram avaliadas?','Registrar pontos quentes, exaustão, coifas, ventilação, hidratação e necessidade de avaliação quantitativa.'),
 (140,'NR-07','Saúde ocupacional','ASOs e PCMSO contemplam as funções de cozinha, limpeza, estoque, salão e entrega, quando existentes?','Verificar compatibilidade dos exames e monitoramento de queixas osteomusculares, dermatológicas ou de calor.'),
 (150,'NR-11','Estoque e recebimento','Estoque, prateleiras, empilhamento, câmara fria e recebimento de mercadorias estão seguros?','Verificar estabilidade, acesso, altura, integridade de prateleiras, iluminação e circulação.'),
 (160,'NR-01','Câmara fria','Há procedimento seguro para acesso à câmara fria e comunicação/emergência para trabalhador retido?','Verificar abertura interna, alarme/comunicação, iluminação, vestimenta térmica e controle de entrada. N/A somente se não houver câmara fria.'),
 (170,'NR-05','Treinamento e rotina','A equipe foi orientada sobre cortes, queimaduras, GLP, produtos químicos, limpeza e emergência?','Conferir integração, reciclagens, registros e instruções visíveis na rotina.'),
 (180,'NR-01','Resíduos e limpeza','A coleta e o descarte de resíduos, óleo, vidro e materiais perfurocortantes ocorrem sem risco à equipe?','Observar recipientes, frequência, segregação, higienização e rota de retirada.')
) v(ord,nr,section,prompt,guidance)
on conflict (profile_id,sort_order) do update set regulatory_standard_code=excluded.regulatory_standard_code,section_title=excluded.section_title,prompt=excluded.prompt,guidance=excluded.guidance,required=excluded.required;
